head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.secugrpId = "";        // 증권그룹ID — 종목 찾기에 쓴다. 이 메뉴는 PF(상장형 수익증권) 고정 (원본 fr_SecuGrpId)
scwin.POPUP_URL = "/ui/lst/pf/ULDSTF09306.xml";     // 변경상장관리 팝업 — 원본 리터럴(pf 공통 계약서 §2)
scwin.FORM_CD_CANCEL = "69780";                     // 변경상장 취소 서식 — 이 서식 행은 관리 팝업을 열지 않는다(§8 #4)

// 원본 : ULDSTF09304.xml (W-Craft 1차 변환 + API 적용 개발 사본, meta_asisFileNm ULDSTF09304.gfm)
/*
 * 화면 동작
 *  - 열리면 발행예정내역(변경상장신청서 접수 — 전체 종목)을 조회한다.
 *  - [종목 찾기](ULDSTF92017, PF)로 종목을 고르거나 발행예정내역 행을 클릭하면 그 종목의 증권발행내역을 조회한다.
 *  - 발행예정내역 행 더블클릭은 접수(R), 증권발행내역 행은 이력(H), [신규]는 신규(N)로 변경상장관리 팝업(ULDSTF09306)을 연다.
 *  - 팝업이 닫히면(저장·수정·삭제·창 닫기) 두 목록을 다시 조회한다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF09304/ULDSTF09304.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 증권그룹ID → 조회 Enter 키 바인딩 → 발행예정내역 조회. (원본 scwin.init → fn_recv_list_sync — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 증권그룹ID — 이 메뉴는 업무공통 표에서 PF(상장형 수익증권) 하나다
    scwin.secugrpId = $c.lc.glb.SECUGRP_ID_PF;

    // 2) 조회 영역 Enter 키(1회, 규칙 22)
    $c.win.setEnterKeyEvent(panel_Top, scwin.btn_Search_onclick);

    // 3) 발행예정내역 — 원본도 열릴 때 이 목록만 조회한다(증권발행내역은 종목을 고른 뒤)
    await scwin.selectRecvList();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 버튼 클릭 (조회 영역 Enter 키도 이 핸들러)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_ISU_CD_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(돋보기) 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_ISU_CD_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.img_ISU_CD_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_Recv_oncellclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행예정내역 행 클릭 — 그 종목을 조회 영역에 넣고 증권발행내역을 조회한 뒤 일자를 확인한다. (원본 grd_Recv_oncellclick)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_Recv_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.selectRecv(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.grd_Recv_oncellclick" });
    }
};

/**
 * @method
 * @name scwin.grd_Recv_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행예정내역 행 더블클릭 — 접수(R)로 변경상장관리 팝업을 연다. (원본 grd_Recv_oncelldblclick → fn_OpenDetailRecv)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_Recv_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openDetailRecv(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.grd_Recv_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.grd_List_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 증권발행내역 행 더블클릭 — 이력(H)으로 변경상장관리 팝업을 연다. (원본 grd_List_oncelldblclick → fn_OpenDetailMng)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_List_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openDetailHist(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.grd_List_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Excel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 엑셀다운로드 버튼 클릭 — 증권발행내역을 내려받는다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Excel_onclick = async function (e) {
    try {
        scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_New_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 버튼 클릭 — 신규(N)로 변경상장관리 팝업을 연다. (원본 btn_New_onclick)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_New_onclick = async function (e) {
    try {
        await scwin.openNew();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09304.btn_New_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectRecvList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행예정내역(변경상장신청서 접수) 목록 조회 — 조건 없이 전체 종목. (원본 fn_recv_list_sync — §5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectRecvList = async function () {
    dlt_recv.removeAll();
    $c.stf.fillGridHeaderTotalCnt(0, edt_TotalCnt_1);

    const sbmOptions = {
        id : "sbm_selectRecvList",
        method : "get",
        action : "/api/listing/lstproc/pf/chglisting/select-list-recv",
        target : "dlt_recv=body",
        gridview : "grd_Recv",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 핸들러

    // 원본은 발행예정내역 건수 자리에 증권발행내역(dlt_list) 건수를 적었다(§8 #2)
    $c.stf.fillGridHeaderTotalCnt(dlt_recv.getRowCount(), edt_TotalCnt_1);
    return true;
};

/**
 * @method
 * @name scwin.selectHistList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 증권발행내역 목록 조회 — 조회 영역의 종목으로. 종목이 없으면 목록을 비운다. (원본 fn_list_sync — §5.2)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectHistList = async function () {
    dlt_list.removeAll();
    $c.stf.fillGridHeaderTotalCnt(0, edt_TotalCnt_2);

    const isuCd = dma_search.get("isuCd");
    if ($c.util.isEmpty(isuCd)) return false;

    const sbmOptions = {
        id : "sbm_selectHistList",
        method : "get",
        action : "/api/listing/lstproc/pf/chglisting/select-list-hist",
        target : "dlt_list=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : isuCd });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 핸들러

    // 원본은 이 건수를 발행예정내역 건수 칸(panel_page)에 적었다 — 증권발행내역 건수 칸으로(§8 #2)
    $c.stf.fillGridHeaderTotalCnt(dlt_list.getRowCount(), edt_TotalCnt_2);
    return true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 — 두 목록을 다시 조회한다. 종목을 고르지 않았으면 증권발행내역은 비운다. (원본 btn_Search_onclick — §6.1)
 * @returns
 * @hidden N
 */
scwin.search = async function () {
    // 원본은 종목이 없으면 아무것도 하지 않았다 — 발행예정내역은 종목과 무관하므로 다시 조회한다(§9)
    await scwin.allListSync();
};

/**
 * @method
 * @name scwin.allListSync
 * @author Inswave
 * @date 2026. 10. 30
 * @description 두 목록 조회 — 발행예정내역 → 증권발행내역 순서. (원본 fn_all_list_sync — §6.1)
 * @returns
 * @hidden N
 */
scwin.allListSync = async function () {
    await scwin.selectRecvList();
    await scwin.selectHistList();
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(ULDSTF92017, PF). 고른 종목을 조회 영역에 넣고 증권발행내역을 조회한다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 img_ISU_CD_onclick — §6.2)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    // 92017 은 행을 고르면 그 행(getRowJSON)을, 창을 닫으면 { isCloseButtonClick } 객체를 돌려준다 — 필드로 판정한다(§8 #6)
    const res = await $c.lc.popFindIsu(scwin.secugrpId);
    if ($c.util.isEmpty(res?.isuCd)) return;

    dma_search.set("isuCd", String(res.isuCd));
    dma_search.set("isuNm", String(res.isuKorNm ?? ""));
    dma_search.set("isurCd", String(res.isurCd ?? ""));
    await scwin.selectHistList();    // 원본도 증권발행내역만 다시 조회한다
};

/**
 * @method
 * @name scwin.selectRecv
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행예정내역 행 선택 — 그 행의 종목·발행기관을 조회 영역에 넣고 증권발행내역을 조회한 뒤 일자를 확인한다.
 * (원본 grd_Recv_oncellclick — §6.3)
 * @param {Number} rowIndex 발행예정내역 행 인덱스(화면 번호)
 * @returns
 * @hidden N
 */
scwin.selectRecv = async function (rowIndex) {
    dma_search.set("isuCd", String(dlt_recv.getCellData(rowIndex, "isuCd") ?? ""));
    dma_search.set("isuNm", String(dlt_recv.getCellData(rowIndex, "isuKorNm") ?? ""));
    // 원본은 발행기관코드를 더블클릭 때만 바꿔, 행 클릭 뒤 [신규]가 앞 종목의 발행기관으로 열렸다(§8 #5)
    dma_search.set("isurCd", String(dlt_recv.getCellData(rowIndex, "isurCd") ?? ""));

    await scwin.selectHistList();
    await scwin.checkRecvDate(rowIndex);
};

/**
 * @method
 * @name scwin.checkRecvDate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행예정내역 일자 확인 — 변경상장 예정일이 설정및환매일과 같거나 앞이면 안내한다(취소 서식 제외).
 * (원본 fn_List_Benf_Estb_DD_check — §6.4)
 * @param {Number} rowIndex 발행예정내역 행 인덱스(화면 번호)
 * @returns
 * @hidden N
 */
scwin.checkRecvDate = async function (rowIndex) {
    if (dlt_recv.getCellData(rowIndex, "disclsMaindocFormCd") === scwin.FORM_CD_CANCEL) return;

    const benfDd = String(dlt_recv.getCellData(rowIndex, "benfcertEstbrepurDd") ?? "");
    const listDd = String(dlt_recv.getCellData(rowIndex, "listDd") ?? "");
    // 원본은 둘 다 비어도("" <= "") 안내했다 — 두 일자가 있을 때만 비교한다(§8 #7)
    if ($c.util.isEmpty(benfDd) || $c.util.isEmpty(listDd)) return;

    if (listDd <= benfDd) {
        await $c.win.alert("변경상장 예정일 및 설정 또는 환매일을 확인해 주시기 바랍니다.");
    }
};

/**
 * @method
 * @name scwin.openDetailRecv
 * @author Inswave
 * @date 2026. 10. 30
 * @description 접수 행 열기 — 접수(R)로 관리 팝업을 연다. 변경상장 취소 서식 행은 열지 않는다. (원본 fn_OpenDetailRecv — §6.5)
 * @param {Number} rowIndex 발행예정내역 행 인덱스(화면 번호)
 * @returns
 * @hidden N
 */
scwin.openDetailRecv = async function (rowIndex) {
    // TODO: 변경상장 취소 팝업(ULDSTF09321)은 저장소에 없고 원본도 "TOBE에서 사용X" 로 막았다 (§10 #2)
    if (dlt_recv.getCellData(rowIndex, "disclsMaindocFormCd") === scwin.FORM_CD_CANCEL) return;

    const row = dlt_recv.getRowJSON(rowIndex);
    // 원본은 앞서 이력 행을 더블클릭할 때 남은 업무처리번호(clickBzProcsNo)를 그대로 넘겼다 — 접수 행 값으로(§8 #3)
    await scwin.openDetailPopup("R", String(row.bzProcsNo ?? ""), String(row.acptNo ?? ""), String(row.isurCd ?? ""),
        String(row.isuCd ?? ""), String(row.isuKorNm ?? ""));
};

/**
 * @method
 * @name scwin.openDetailHist
 * @author Inswave
 * @date 2026. 10. 30
 * @description 이력 행 열기 — 그 행의 업무처리번호로 이력(H) 관리 팝업을 연다. (원본 fn_OpenDetailMng + fn_setBzProcsNo — §6.5)
 * @param {Number} rowIndex 증권발행내역 행 인덱스(화면 번호)
 * @returns
 * @hidden N
 */
scwin.openDetailHist = async function (rowIndex) {
    const bzProcsNo = String(dlt_list.getCellData(rowIndex, "bzProcsNo") ?? "");
    const isurCd = String(dlt_list.getCellData(rowIndex, "isurCd") ?? "");
    await scwin.openDetailPopup("H", bzProcsNo, "", isurCd, dma_search.get("isuCd"), dma_search.get("isuNm"));
};

/**
 * @method
 * @name scwin.openNew
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 — 종목을 골랐으면 신규(N)로 관리 팝업을 연다. (원본 btn_New_onclick — §6.6)
 * @returns
 * @hidden N
 */
scwin.openNew = async function () {
    if ($c.util.isEmpty(dma_search.get("isuCd"))) {
        await $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return;
    }
    // 원본의 최초 신규 "X"(목록이 모두 0건)는 곧바로 "N" 으로 덮여 쓰이지 않았다(§8 #8)
    await scwin.openDetailPopup("N", "", "", dma_search.get("isurCd"), dma_search.get("isuCd"), dma_search.get("isuNm"));
};

/**
 * @method
 * @name scwin.openDetailPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 변경상장관리 팝업(ULDSTF09306)을 열고 닫힐 때까지 기다린 뒤, 저장·삭제했거나 창을 닫았으면 두 목록을 다시 조회한다.
 * 팝업은 $c.data.getParameter() 로 받는다 — 평면 키(pf 공통 계약서 §2 09306, 05700→05710 선례). (원본 fn_OpenPopup — §6.7)
 * @param {String} openTyp 여는 방식 R: 접수, H: 이력, N: 신규
 * @param {String} bzProcsNo 업무처리번호 (N 은 "")
 * @param {String} acptNo 접수번호 (R 만)
 * @param {String} isurCd 발행기관코드
 * @param {String} isuCd 종목코드
 * @param {String} isuNm 종목명
 * @returns
 * @hidden N
 */
scwin.openDetailPopup = async function (openTyp, bzProcsNo, acptNo, isurCd, isuCd, isuNm) {
    // 원본은 { pData : {...} } 로 한 겹 감싸고 키에 v 접두(vAcptNo 등)를 붙였다 — 평면 camelCase 로(§8 #9)
    const data = {
        openTyp : openTyp,
        bzProcsNo : bzProcsNo,
        acptNo : acptNo,
        isurCd : isurCd,
        isuCd : isuCd,
        isuNm : isuNm
    };
    // 원본 팝업 id "ULDSTF41621" 은 다른 화면 ID 였다(§8 #1)
    const res = await $c.win.openPopup(scwin.POPUP_URL,
        { id : "ULDSTF09306", popupName : "상장형수익증권변경상장관리", width : 1400, height : 430, type : "pageFramePopup" }, data);

    // 원본 if (res) 는 객체가 늘 참이라 늘 재조회했다 — 계약대로 저장·삭제(isSaved) 또는 창 닫기(isCloseButtonClick)면 재조회(§8 #10)
    if (res?.isSaved === true || res?.isCloseButtonClick === true) {
        await scwin.allListSync();
        scwin.focusHistRow(bzProcsNo);
    }
};

/**
 * @method
 * @name scwin.focusHistRow
 * @author Inswave
 * @date 2026. 10. 30
 * @description 재조회한 증권발행내역에서 열었던 업무처리번호 행에 포커스를 되돌린다(없으면 그대로).
 * @param {String} bzProcsNo 업무처리번호
 * @returns
 * @hidden N
 */
scwin.focusHistRow = function (bzProcsNo) {
    if ($c.util.isEmpty(bzProcsNo)) return;

    const cnt = dlt_list.getRowCount();
    for (let i = 0; i < cnt; i++) {
        if (dlt_list.getCellData(i, "bzProcsNo") === bzProcsNo) {
            grd_List.setFocusedCell(i, 0);
            return;
        }
    }
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 30
 * @description 증권발행내역을 엑셀로 내려받는다. 0건 안내는 공통 함수가 한다. (원본 btn_Excel_onclick — §6.8)
 * @returns
 * @hidden N
 */
scwin.excelDown = function () {
    $c.data.downloadGridViewExcel(grd_List, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42)
        fileName : $c.win.getProgramId() + "_PF변경상장내역_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "리스트"
    });
};
